import { DynamoDBClient, GetItemCommand, PutItemCommand, UpdateItemCommand } from "@aws-sdk/client-dynamodb";
import { quotaExceeded } from "./problems.mjs";

// The cap on Spaces created without a coupon.
//
// Two paths create a Space (and so an S3 bucket) without a coupon: an
// unlock Space, whose id is derived from the signing did:key (any key
// holder, no account needed: this is how a FreeWallet client binds a
// passphrase or passkey), and, with the OpenProvisioning parameter on,
// any Space created by id. Both draw on one global counter kept in the
// registry table under a sentinel key, reserved with a conditional
// increment before the bucket is created and released when such a Space
// is deleted. Past the cap (`MAX_COUPONLESS_SPACES`, default 200) the
// creation is the spec's 507 quota-exceeded; a cap of 0 closes both paths.
// Spaces created with a coupon (`POST /spaces/`, which our own wallet uses
// for every Space it creates) never count.
//
// The registry row records how a Space was provisioned (`provisioning`:
// "coupon", "derived", "open"). Rows from before this attribute existed
// are read by their id form: a server-assigned id was coupon-created,
// anything else was an unlock Space. The feed sweep recounts from the rows
// and backfills the attribute.

const dynamo = new DynamoDBClient({});
const SPACES_TABLE = process.env.SPACES_TABLE_NAME ?? "was-spaces";

export const COUNTER_KEY = "urn:was-server-aws:couponless-spaces";

export const maxCouponlessSpaces = () => Number(process.env.MAX_COUPONLESS_SPACES ?? "200");

const SERVER_ASSIGNED_ID_RE = /^dcc-was-[0-9a-f-]{36}$/;

export const isCounterRow = (row) => row?.spaceURL?.S === COUNTER_KEY;

// How a registry row's Space was provisioned, for rows with and without
// the attribute.
export function provisioningOf(row) {
  const recorded = row?.provisioning?.S;
  if (recorded !== undefined) {
    return recorded;
  }
  const id = row?.spaceURL?.S?.split("/space/")[1];
  return typeof id === "string" && !SERVER_ASSIGNED_ID_RE.test(id) ? "derived" : "coupon";
}

export const isCouponlessRow = (row) => !isCounterRow(row) && provisioningOf(row) !== "coupon";

const counterKey = () => ({ spaceURL: { S: COUNTER_KEY } });

// Takes one slot under the cap, or throws the 507.
export async function reserveCouponlessSlot({ max = maxCouponlessSpaces() } = {}) {
  const refusal = () => quotaExceeded(`This server creates at most ${max} Spaces without a coupon, and that many exist.`);
  if (!(max > 0)) {
    throw refusal();
  }
  try {
    await dynamo.send(
      new UpdateItemCommand({
        TableName: SPACES_TABLE,
        Key: counterKey(),
        UpdateExpression: "ADD #count :one",
        ConditionExpression: "attribute_not_exists(#count) OR #count < :max",
        ExpressionAttributeNames: { "#count": "count" },
        ExpressionAttributeValues: { ":one": { N: "1" }, ":max": { N: String(max) } },
      })
    );
  } catch (err) {
    if (err?.name === "ConditionalCheckFailedException") {
      throw refusal();
    }
    throw err;
  }
}

// Gives a slot back (a deleted coupon-less Space, or a creation that
// failed after reserving); never below zero.
export async function releaseCouponlessSlot() {
  try {
    await dynamo.send(
      new UpdateItemCommand({
        TableName: SPACES_TABLE,
        Key: counterKey(),
        UpdateExpression: "ADD #count :minus",
        ConditionExpression: "#count > :zero",
        ExpressionAttributeNames: { "#count": "count" },
        ExpressionAttributeValues: { ":minus": { N: "-1" }, ":zero": { N: "0" } },
      })
    );
  } catch (err) {
    if (err?.name !== "ConditionalCheckFailedException") {
      throw err;
    }
  }
}

export async function readCouponlessCount() {
  const { Item } = await dynamo.send(new GetItemCommand({ TableName: SPACES_TABLE, Key: counterKey() }));
  return Number(Item?.count?.N ?? 0);
}

export async function setCouponlessCount(count) {
  await dynamo.send(new PutItemCommand({ TableName: SPACES_TABLE, Item: { ...counterKey(), count: { N: String(count) } } }));
}
